import json, pathlib
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak, KeepTogether

H = pathlib.Path(__file__).parent; R = json.load(open(H / "results.json")); FIG = H / "figures"
ss = getSampleStyleSheet()
B = ParagraphStyle("B", parent=ss["BodyText"], fontSize=9.2, leading=12.4, spaceAfter=4)
H1 = ParagraphStyle("H1", parent=ss["Heading1"], fontSize=14, spaceBefore=8, spaceAfter=6)
H2 = ParagraphStyle("H2", parent=ss["Heading3"], fontSize=10.5, spaceBefore=6, spaceAfter=3, textColor=colors.HexColor("#1F3A5F"))
SM = ParagraphStyle("SM", parent=B, fontSize=8, leading=10.5)
S = []
def P(t, st=B): S.append(Paragraph(t, st))
def T(rows, widths=None, head=True, fs=8):
    t = Table([[Paragraph(str(c), SM) if isinstance(c, str) and len(str(c)) > 11 else c for c in r] for r in rows], colWidths=widths, repeatRows=1 if head else 0)
    st = [("GRID", (0, 0), (-1, -1), .4, colors.grey), ("FONTSIZE", (0, 0), (-1, -1), fs), ("VALIGN", (0, 0), (-1, -1), "TOP")]
    if head: st += [("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#DDEBF7")), ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold")]
    t.setStyle(TableStyle(st)); S.append(KeepTogether([t])); S.append(Spacer(1, 5))
def IMG(n, w=17): 
    from PIL import Image as PI
    iw, ih = PI.open(FIG / n).size; S.append(Image(str(FIG / n), width=w * cm, height=w * cm * ih / iw))
def f(x, d=3): return f"{x:,.{d}f}"
def pf(p): return "&lt; 0.001" if p < 0.001 else f"{p:.3f}"

q1, q2, q3, q4, q5, q6, q8 = (R[k] for k in ("Q1", "Q2", "Q3", "Q4", "Q5", "Q6", "Q8")); q7 = R["Q7"]

