S.append(PageBreak()); P("Question 1 - Normality testing (Lilliefors)", H1)
P(f"<b>Data.</b> Viet Nam CPI inflation (FP.CPI.TOTL.ZG), annual %, {q1['years'][0]}-{q1['years'][1]}, n = {q1['n']} (≥ 20 required). Mean = {f(q1['mean'],2)}, s = {f(q1['sd'],2)}, median {f(q1['median'],2)}, min {f(q1['min'],2)}, max {f(q1['max'],2)} ({q1['argmax_year']}), skewness {f(q1['skew'],2)}, excess kurtosis {f(q1['kurt_excess'],2)}.")
P("<b>Hypotheses.</b> H0: inflation is drawn from a normal distribution (mean and variance unknown, estimated from the sample); H1: it is not. <b>Test.</b> Lilliefors = Kolmogorov-Smirnov with parameters estimated: D = max<sub>i</sub> max{ i/n - F(z<sub>i</sub>), F(z<sub>i</sub>) - (i-1)/n }, z<sub>i</sub> = (x<sub>(i)</sub> - mean)/s, F = standard-normal CDF. Ordered observations, z-values, theoretical and empirical CDFs are in workbook sheet <i>Q1</i> (live formulas) and tables/Q1_lilliefors.csv.")
first = [["i", "x(i) %", "Year", "z", "F theor.", "i/n", "D+", "D-"]]
